def write_json_with_two_decimal_floats(obj, path):
    def render(value, indent_level=0):
        indent = '  ' * indent_level
        child_indent = '  ' * (indent_level + 1)

        if isinstance(value, dict):
            if not value:
                return '{}'
            parts = []
            for key, item in value.items():
                parts.append(f'{child_indent}{json.dumps(key)}: {render(item, indent_level + 1)}')
            return '{\n' + ',\n'.join(parts) + '\n' + indent + '}'
        if isinstance(value, list):
            if not value:
                return '[]'
            parts = [f'{child_indent}{render(item, indent_level + 1)}' for item in value]
            return '[\n' + ',\n'.join(parts) + '\n' + indent + ']'
        if isinstance(value, float):
            return f'{value:.2f}'
        return json.dumps(value)

    path.write_text(render(obj) + '\n')


def write_summary(report):
    totals = report['analysis']['totals']
    decision = report['analysis']['recommendation']['decision']
    lines = [
        '# Reagent Policy Summary',
        f"Total small-kit margin (USD): {totals['total_annual_margin_small_kit_usd']:.2f}",
        f"Total bulk-kit margin (USD): {totals['total_annual_margin_bulk_kit_usd']:.2f}",
        f"Absolute difference (USD): {totals['absolute_total_margin_difference_usd']:.2f}",
        f"Decision: {decision}",
    ]
    (ROOT / 'reagent_policy_summary.md').write_text('\n'.join(lines) + '\n')


def main():
    report = build_report()
    write_json_with_two_decimal_floats(report, ROOT / 'reagent_policy_report.json')
    write_summary(report)

